package com.fxrates.ui

/**
 * Every user-facing string of the app. The app is English-only, so a constant is enough; a
 * string is never written inline in a composable.
 */
object Strings {

    const val RATES_TITLE = "Rates"
    const val RATES_SEARCH_HINT = "Search by code or name"
    const val RATES_NOTHING_FOUND = "Nothing found"
    const val ERROR_TITLE = "Could not load the rates"
    const val RETRY = "Retry"
    const val REFRESH = "Refresh"

    fun ratesSubtitle(base: String, date: String): String = "1 $base · $date"

}
package com.fxrates.core.money

import com.ionspin.kotlin.bignum.decimal.BigDecimal
import com.ionspin.kotlin.bignum.decimal.DecimalMode
import com.ionspin.kotlin.bignum.decimal.RoundingMode
import com.ionspin.kotlin.bignum.decimal.toBigDecimal

/**
 * The change between two rates of the same currency pair.
 *
 * @property absolute `current - previous`, in units of the quote currency.
 * @property percent the change relative to the previous rate; `1.5` means +1.5%. Computed in [BigDecimal],
 * rounded to 20 significant digits when the quotient does not terminate.
 */
data class RateChange(
    val absolute: BigDecimal,
    val percent: BigDecimal,
)

object RateChangeCalculator {

    /** Returns `null` when [previous] is zero and the relative change is undefined. */
    fun calculate(previous: BigDecimal, current: BigDecimal): RateChange? {
        if (previous.isZero()) return null
        val absolute = current - previous
        val percent = absolute.divide(previous, PERCENT_DECIMAL_MODE) * HUNDRED
        return RateChange(absolute = absolute, percent = percent)
    }

    private val PERCENT_DECIMAL_MODE = DecimalMode(
        decimalPrecision = 20,
        roundingMode = RoundingMode.ROUND_HALF_AWAY_FROM_ZERO,
    )

    private val HUNDRED = 100.toBigDecimal()

}
package com.fxrates.feature.rates.details.mvi

import com.arkivanov.mvikotlin.core.store.Store
import com.fxrates.core.utils.Resource
import com.fxrates.domain.model.RatePoint

internal class RateDetailsStore(
    store: Store<Intent, State, Label>,
) : Store<RateDetailsStore.Intent, RateDetailsStore.State, RateDetailsStore.Label> by store {

    sealed class Intent {

        data object OnRetry : Intent()

        data object OnBackClick : Intent()

    }

    sealed class Action {

        data class LoadHistory(val base: String, val code: String) : Action()

    }

    sealed class Message {

        data class UpdateHistory(val history: Resource<List<RatePoint>>) : Message()

    }

    sealed class Label {

        data object Back : Label()

    }

    data class State(
        val base: String,
        val code: String,
        val history: Resource<List<RatePoint>> = Resource.Loading,
    )

}
